import Foundation

/// harness.v1 envelope, generated by swift-openapi-generator from openapi/capcomd.json (events.replay item schema).
/// Live SSE frames carry the same envelope (`id: <seq>`, `event: <type>`, `data: <envelope>`).
public typealias HarnessEvent = Operations.events_period_replay.Output.Ok.Body.jsonPayloadPayload

/// One item of the contract stream: `stream.reset` → `snapshot.*` (raw JSON) → `snapshot.end` → live events.
public enum StreamItem: Sendable, Hashable {
  case reset(snapshotSeq: Int, reason: String)
  case snapshot(name: String, json: String)
  case snapshotEnd(snapshotSeq: Int)
  case event(HarnessEvent)
}
public struct StreamStats: Sendable {
  public var connections = 0; public var resets = 0; public var drops = 0; public var dupesDropped = 0
  public var heartbeats = 0; public var idleTimeouts = 0
}

/// Resumable stream on `GET /v1/streams/{scope}/events`: resumes with Last-Event-ID, applies reset+snapshot in-band
/// (cursor jumps to snapshotSeq at `snapshot.end`), dedupes by seq, and treats `idleTimeout` of silence as a dead socket.
public actor ResumableEventStream {
  let transport: UnixSocketTransport; let path: String
  public private(set) var lastSeq: Int; public private(set) var stats = StreamStats()
  let maxReconnects: Int; let backoff: Duration; let idleTimeout: Duration
  public init(transport: UnixSocketTransport, scope: String = "run-demo", startAfter: Int = 0, maxReconnects: Int = 10,
              backoff: Duration = .milliseconds(50), idleTimeout: Duration = .seconds(45)) {
    self.transport = transport; self.path = "/v1/streams/\(scope)/events"; self.lastSeq = startAfter
    self.maxReconnects = maxReconnects; self.backoff = backoff; self.idleTimeout = idleTimeout
  }

  struct ResetBody: Decodable { var snapshotSeq: Int; var reason: String }
  struct EndBody: Decodable { var snapshotSeq: Int }

  /// Runs until the server ends the stream cleanly or `until` returns true.
  public func run(until: @Sendable (StreamItem) -> Bool = { _ in false }, onItem: @Sendable (StreamItem) async -> Void) async throws {
    var attempts = 0
    while true {
      stats.connections += 1
      var inSnapshot = false
      do {
        let items = transport.sseItems(path, lastEventID: lastSeq > 0 ? String(lastSeq) : nil, idleTimeout: idleTimeout)
        for try await item in items {
          guard case .frame(let f) = item else { stats.heartbeats += 1; continue }
          let d = Data(f.data.utf8); let it: StreamItem
          switch f.event {
          case "stream.reset":
            let r = try JSONDecoder().decode(ResetBody.self, from: d); stats.resets += 1; inSnapshot = true
            it = .reset(snapshotSeq: r.snapshotSeq, reason: r.reason)
          case "snapshot.end":
            let e = try JSONDecoder().decode(EndBody.self, from: d); lastSeq = e.snapshotSeq; inSnapshot = false; attempts = 0
            it = .snapshotEnd(snapshotSeq: e.snapshotSeq)
          case let n where n.hasPrefix("snapshot."):
            it = .snapshot(name: n, json: f.data)
          default:
            if inSnapshot { continue } // live events only after snapshot.end
            let e = try JSONDecoder.harness.decode(HarnessEvent.self, from: d)
            guard e.seq > lastSeq else { stats.dupesDropped += 1; continue }
            lastSeq = e.seq; attempts = 0
            it = .event(e)
          }
          await onItem(it); if until(it) { return }
        }
        return // clean end
      } catch let e as HTTPStatusError { throw e } // 401 etc: don't retry
      catch {
        if error is SSEIdleTimeout { stats.idleTimeouts += 1 } else { stats.drops += 1 }
        attempts += 1
        if attempts > maxReconnects { throw error }
        try await Task.sleep(for: backoff * attempts)
      }
    }
  }
}
